void fifo_insert( Fifo_List fifo , Fifo_Node *node )
{
	fifo->rhs->lhs = node ; 
	
	node->rhs = fifo->rhs ; 
	
	node->lhs = fifo ; 

	fifo->rhs = node ;
}
	
